/* memory panel */
.mm{max-width:420px}
.mm-head{display:flex;align-items:center;justify-content:space-between;padding:14px 16px;border-bottom:1px solid var(--line)}
.mm-head .t{font-size:15px;font-weight:600}
.mm-sub{margin-top:2px;font-size:12.5px;color:var(--muted)}
.mm-list{padding:6px 8px}
.mm-g{padding:8px 8px 4px;font-size:11.5px;font-weight:600;color:var(--muted)}
.mm-it{position:relative;display:flex;align-items:flex-start;gap:10px;padding:8px;transition:background-color .15s,opacity .3s}
.mm-it:hover{background:var(--chip)}
.mm-it .mm-pin{color:var(--accent);margin-top:1px}
.mm-tx{flex:1;min-width:0}
.mm-tx .t{font-size:13.5px;line-height:1.45;color:var(--text)}
.mm-tx .s{margin-top:2px;font-size:12px;color:var(--muted)}
.mm-acts{display:flex;gap:2px;opacity:0;transition:opacity .15s}
.mm-it:hover .mm-acts,.mm-it:focus-within .mm-acts{opacity:1}
.mm-acts button{width:26px;height:26px;display:grid;place-items:center;color:var(--muted)}
.mm-acts button:hover{color:var(--text)}
.mm-acts button.on{color:var(--accent)}
.mm.off .mm-list{opacity:.4;pointer-events:none}
.mm-add{display:flex;gap:8px;padding:10px 12px;border-top:1px solid var(--line)}
.mm-add input{flex:1;min-width:0;height:32px;padding:0 10px;background:var(--panel);border:1px solid var(--icon-line);outline:0;font:inherit;font-size:13.5px;color:var(--text)}
.mm-add input:focus{border-color:var(--accent)}

/* ---------- memory panel ---------- */
{
  const mm = $('#mm'), list = $('#mm-list'), sub = $('#mm-sub');
  let items = [
    { g:'About you', t:'Prefers short answers with the decision first', s:'From chat, 2 days ago', pin:true },
    { g:'About you', t:'Works in GMT+2 and is offline after 6pm', s:'From settings' },
    { g:'About you', t:'Writes in British English', s:'From chat, last week' },
    { g:'Pricing page project', t:'Plan names are Starter, Pro and Team', s:'From Pricing.fig', pin:true },
    { g:'Pricing page project', t:'Launch date is 14 November', s:'From the project brief' },
    { g:'Pricing page project', t:'Maya Chen signs off on design changes', s:'From chat, yesterday' }
  ];
  function render(){
    const groups = [...new Set(items.map(i => i.g))];
    list.innerHTML = groups.map(g => `<div class="mm-g">${g}</div>` + items.map((it, i) => it.g !== g ? '' : `<div class="mm-it" data-i="${i}">${it.pin ? ic('push_pin','sm mm-pin') : ic('history','sm')}<div class="mm-tx"><div class="t">${esc(it.t)}</div><div class="s">${it.s}</div></div><div class="mm-acts"><button data-a="pin" class="${it.pin ? 'on' : ''}" aria-label="${it.pin ? 'Unpin' : 'Pin'}">${ic('push_pin','sm')}</button><button data-a="forget" aria-label="Forget">${ic('close','sm')}</button></div></div>`).join('')).join('');
    sub.textContent = items.length + (items.length === 1 ? ' memory' : ' memories');
  }
  list.addEventListener('click', e => {
    const b = e.target.closest('[data-a]'); if (!b) return; const row = b.closest('.mm-it'), i = +row.dataset.i;
    if (b.dataset.a === 'pin'){ items[i].pin = !items[i].pin; Sound.play('tick'); morph(list.parentElement, render); }
    else { const gone = items.splice(i, 1)[0]; row.style.opacity = '0'; Sound.play('close'); setTimeout(() => morph(list.parentElement, render), 200); showToast('Forgot: ' + gone.t); }
  });
  const add = () => { const v = $('#mm-in').value.trim(); if (!v) return; items.unshift({ g:'About you', t:v, s:'Added just now' }); $('#mm-in').value = ''; Sound.play('pop'); morph(list.parentElement, render); };
  $('#mm-go').addEventListener('click', add); $('#mm-in').addEventListener('keydown', e => { if (e.key === 'Enter') add(); });
  $('#mm-on').addEventListener('click', e => { const on = e.currentTarget.getAttribute('aria-checked') !== 'true'; e.currentTarget.setAttribute('aria-checked', on); mm.classList.toggle('off', !on); swapText(sub, on ? items.length + ' memories' : 'Memory paused'); Sound.play(on ? 'on' : 'off'); });
  render();
}
